"""Generate the desktop's TypeScript event types from ``panos_core.event_catalog`` (M7-02).

Usage: ``python scripts/export_event_types.py <out.ts>`` (``--check`` compares instead).
"""

import sys
from pathlib import Path

from panos_core.domain.enums import JobStatus
from panos_core.event_catalog import EVENT_TYPES, JOB_STATUSES
from panos_core.events import EVENT_SCHEMA_VERSION

HEADER = (
    "// Generated by scripts/export_event_types.py from panos_core.event_catalog.\n"
    "// Do not edit by hand: run `pnpm gen`.\n\n"
)


def _name(event_type: str) -> str:
    return (
        "".join(part.capitalize() for part in event_type.replace("_", ".").split(".")) + "Payload"
    )


def render() -> str:
    if tuple(s.value for s in JobStatus) != JOB_STATUSES:
        raise SystemExit("event_catalog.JOB_STATUSES is out of date with JobStatus")
    lines = [
        HEADER,
        f"export const EVENT_SCHEMA_VERSION = {EVENT_SCHEMA_VERSION};\n\n",
        "export type JobStatus =\n" + "\n".join(f'  | "{s}"' for s in JOB_STATUSES) + ";\n\n",
    ]
    for event_type, fields in EVENT_TYPES.items():
        body = "".join(f"  {name}: {ts};\n" for name, ts in fields.items())
        lines.append(f"export interface {_name(event_type)} {{\n{body}}}\n\n")
    lines.append(
        "export interface EventPayloads {\n"
        + "".join(f'  "{t}": {_name(t)};\n' for t in EVENT_TYPES)
        + "}\n\n"
    )
    lines.append(
        "export type EventType = keyof EventPayloads;\n\n"
        "/** The /ws/events envelope (ADR-018). */\n"
        "export interface PanosEvent<T extends EventType = EventType> {\n"
        "  v: number;\n  seq: number;\n  type: T;\n  id: string;\n  ts: string;\n"
        "  correlation_id: string | null;\n  job_id: string | null;\n"
        "  payload: EventPayloads[T];\n}\n\n"
        'export interface AuthOk {\n  type: "auth.ok";\n  v: number;\n  epoch: string;\n'
        '  seq: number;\n}\n\nexport interface Resync {\n  type: "resync";\n  seq: number;\n}\n\n'
        "export type ServerMessage = PanosEvent | AuthOk | Resync;\n\n"
        "export const EVENT_TYPES: readonly EventType[] = [\n"
        + "".join(f'  "{t}",\n' for t in EVENT_TYPES)
        + "];\n"
    )
    return "".join(lines)


def main() -> None:
    args = [a for a in sys.argv[1:] if a != "--check"]
    target = Path(args[0]) if args else Path("apps/desktop/src/api/events.ts")
    text = render()
    if "--check" in sys.argv:
        current = target.read_text(encoding="utf-8") if target.exists() else ""
        if current != text:
            raise SystemExit(f"{target} is out of date: run `pnpm gen`")
        print(f"OK: {target} is up to date")
        return
    target.write_bytes(text.encode("utf-8"))
    print(f"wrote {target}")


if __name__ == "__main__":
    main()
